/* src/kernel/scrollbars.css */
/*
 * v7 固定全局无滚动条外观内核。
 * 只隐藏浏览器滚动条外观，不修改 overflow、touch-action、pointer-events，
 * 不隐藏滚动容器、跳转键、功能按钮或 input[type="range"]。
 * 全局 * 是本项目唯一允许的无边界选择器例外，不得增加其他声明。
 */
::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}


/* src/tokens.css */
@font-face {
 font-family: "Noto Serif SC";
 src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/notoserifsc/notoserifsc.woff2") format("woff2");
 font-weight: 200 900;
 font-style: normal;
 font-display: swap;
}

:root {
  --theme-sky: #8bbce1;
  --theme-surface: #fff8e8;
  --theme-surface-muted: #dcecf5;
  --theme-surface-disabled: #d3e8f7;
  --theme-text-primary: #143d69;
  --theme-text-secondary: #41688a;
  --theme-text-disabled: #436e9b;
  --theme-border: #c9b67c;
  --theme-focus-ring: #26739c;
  --theme-gold: #efce7e;
  --theme-quote: #fff0c5;
  --theme-leaf: #39796f;
  --theme-error: #9a443f;
  --theme-warning: #866020;
  --theme-success: #2c7162;
  --theme-shadow: 0 4px 12px #3c709526;
  --theme-raised: inset 0 2px 0 #fffdf2, inset 0 -3px 0 #aecde0, 0 2px 4px #3c70952b;
  --theme-paper-shadow: inset 0 0 24px #e4cf9429, 0 2px 6px #38648b29;
  --theme-code-inline-surface: #e4eef0;
  --theme-code-block-surface: #e7f1f5;
  --theme-code-text: #153f64;
  --theme-code-muted: #3d678e;
  --theme-code-keyword: #775238;
  --theme-code-string: #286f60;
  --theme-code-number: #7e4561;
  --theme-selection: #c7e2ef;
  --theme-opacity-disabled: 1;
  --st-theme-font-body: "Noto Serif SC", "Songti SC", SimSun, serif;
  --avatar-size: 144px;
  --avatar-gap: 14px;
  --avatar-slot: calc(var(--avatar-size) + var(--avatar-gap));
  --st-theme-mobile-reading-width: 100%;
  --st-theme-mobile-reading-padding: .15em;
  --theme-opacity-full: 1;
  --theme-effect-none: none;
  --theme-current: currentColor;
  --theme-icon-emboss: 0 1px 0 #fff8e8, 0 2px 1px #41688a;
  --tick-content: "✓";
  --tick-size: 1.05em;
  --tick-clip: inset(0);
  --tick-hidden: scale(0);
  --tick-visible: scale(1);
  --theme-enamel: linear-gradient(145deg, #d4edfc, #9ccbef);
  --theme-frame: inset 0 2px 0 #fff8e8, inset 0 -3px 0 #8bbce1, 0 3px 0 #c9b67c;
  --theme-clear: transparent;
  --theme-scroll-auto: auto;
}


/* src/chat-layout.css */
body {
  background-color: var(--theme-sky);
  color: var(--theme-text-primary);
  text-shadow: none;
  --topBarBlockSize: 84px;
  --bottomFormBlockSize: 40px;
  --bottomFormIconSize: 22px;
  --topBarIconSize: 24px;
}

#bg1, #bg_custom {
  background-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/b57b4794b0840c9f2b9ca43b59ab107ec2a1cedd/assets/%E6%98%9F%E6%9C%88%E7%99%BE%E5%90%88/lily-sky.png") !important;
  background-color: var(--theme-sky) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
}

#chat {
  color: var(--theme-text-primary);
  background-color: var(--theme-surface);
  border-color: var(--theme-border);
  opacity: var(--theme-opacity-full);
  filter: var(--theme-effect-none);
  text-shadow: var(--theme-effect-none);
  box-shadow: var(--theme-paper-shadow);
  border: 1px solid var(--theme-border);
  border-radius: 24px 24px 16px 16px;
  backdrop-filter: none;
  padding: 1.1em clamp(.7em, 2.4%, 2em) 1.4em;
  margin-top: 10px;
}

#chat .mes[is_system="false"] {
  flex-direction: column;
  align-items: stretch;
  gap: var(--avatar-gap);
  padding: 1em 0 1.7em;
  border: 0;
  background: transparent;
}

#chat .mes[is_system="false"] > .mesAvatarWrapper {
  flex: 0 0 auto;
  inline-size: var(--avatar-size);
  align-self: center;
  margin: 0 auto;
  padding-bottom: 0;
  position: relative;
}

#chat .mes[is_system="false"] > .mesAvatarWrapper .avatar {
  width: var(--avatar-size);
  height: var(--avatar-size);
  border: 4px solid var(--theme-surface);
  border-radius: 4px;
  box-sizing: border-box;
  box-shadow: var(--theme-frame);
  background-color: var(--theme-surface);
}

#chat .mes[is_system="false"] > .mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 2px;
  border: 0;
  box-shadow: none;
}

#chat .mes[is_system="false"] > .mesAvatarWrapper::before {
  content: "";
  position: absolute;
  width: 56px;
  height: 56px;
  top: 100px;
  left: -20px;
  background-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/b57b4794b0840c9f2b9ca43b59ab107ec2a1cedd/assets/%E6%98%9F%E6%9C%88%E7%99%BE%E5%90%88/lily-bloom.png");
  background-size: contain;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 1;
}

#chat .mes[is_system="false"] > .mesAvatarWrapper::after {
  content: "";
  position: absolute;
  width: 44px;
  height: 44px;
  top: -12px;
  right: -20px;
  background-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/b57b4794b0840c9f2b9ca43b59ab107ec2a1cedd/assets/%E6%98%9F%E6%9C%88%E7%99%BE%E5%90%88/lily-bloom.png");
  background-size: contain;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 1;
}

#chat .mes[is_system="false"] > .mes_block {
  flex: 1 1 auto;
  inline-size: 100%;
  box-sizing: border-box;
  min-inline-size: 0;
  padding-inline: 0;
}

#chat .mes[is_user="true"][is_system="false"] > .mes_block {
  color: var(--theme-text-primary);
  background-color: var(--theme-surface-muted);
  border-color: var(--theme-border);
  opacity: var(--theme-opacity-full);
  filter: var(--theme-effect-none);
  text-shadow: var(--theme-effect-none);
  box-shadow: var(--theme-raised);
  border: 1px solid var(--theme-surface-muted);
  border-radius: 20px 28px 20px 10px;
  padding: .65em 1em;
}

#chat .mes[is_system="true"] {
  color: var(--theme-text-secondary);
  background-color: var(--theme-surface-muted);
  border-color: var(--theme-border);
  opacity: var(--theme-opacity-full);
  filter: var(--theme-effect-none);
  text-shadow: var(--theme-effect-none);
  box-shadow: var(--theme-effect-none);
  padding: .65em;
  border-radius: 12px;
}

#chat .mes.selected {
  background-color: var(--theme-selection);
}

#chat .ch_name {
  gap: .35em;
  align-items: baseline;
  margin-bottom: .55em;
}

#chat .name_text {
  color: var(--theme-text-primary);
  font-family: var(--st-theme-font-body);
  font-size: 1.22em;
  font-weight: 700;
  letter-spacing: .045em;
  text-shadow: none;
}

#chat .timestamp, #chat .mesIDDisplay, #chat .mes_timer, #chat .tokenCounterDisplay {
  color: var(--theme-text-secondary);
  font-size: .76em;
  font-family: var(--st-theme-font-body);
  opacity: var(--theme-opacity-full);
  filter: var(--theme-effect-none);
  text-shadow: var(--theme-effect-none);
  box-shadow: var(--theme-effect-none);
}

@media (max-width: 700px) {
body {
  --topBarBlockSize: 64px;
  --bottomFormBlockSize: 30px;
  --bottomFormIconSize: 19px;
  --topBarIconSize: 19px;
}
}

@media (max-width: 700px) {
#chat {
  padding: .55em .7em;
  margin: 5px 5px 0;
  border-radius: 15px;
}
}

@media (max-width: 700px) {
#chat .mes[is_system="false"] {
  flex-direction: column;
  align-items: stretch;
  gap: .35em;
  padding-block: .7em 1em;
}
}

@media (max-width: 700px) {
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  align-self: center;
  margin-inline: auto;
  flex-basis: auto;
}
}

@media (max-width: 700px) {
#chat .mes[is_system="false"] > .mes_block {
  inline-size: 100%;
  min-inline-size: 0;
  flex: 1 1 auto;
  box-sizing: border-box;
}
}

@media (max-width: 700px) {
#chat .mes[is_system="false"] > .mes_block > .mes_text {
  inline-size: min(100%, var(--st-theme-mobile-reading-width));
  max-inline-size: 100%;
  margin-inline: auto !important;
  padding-inline: var(--st-theme-mobile-reading-padding) !important;
  box-sizing: border-box;
}
}


/* src/full-text.css */
#chat .mes_text {
  font-family: var(--st-theme-font-body);
  font-size: 1em;
  font-weight: 500;
  line-height: 1.9;
  letter-spacing: .025em;
  color: var(--theme-text-primary);
  text-shadow: none;
  padding-inline: 0;
  padding-block: .2em;
  overflow-wrap: anywhere;
}

#chat .mes_text p {
  margin: 0 0 1em;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text > p:first-child::first-letter {
  font-size: 2.15em;
  font-weight: 700;
  line-height: 1.25;
  color: var(--theme-text-primary);
  background-color: var(--theme-quote);
  background-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/b57b4794b0840c9f2b9ca43b59ab107ec2a1cedd/assets/%E6%98%9F%E6%9C%88%E7%99%BE%E5%90%88/lily-bloom.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  border-radius: .22em;
  padding: .04em .12em;
  margin-inline-end: .08em;
}

#chat .mes_text :is(h1,h2,h3,h4,h5,h6) {
  color: var(--theme-text-primary);
  font-family: var(--st-theme-font-body);
  font-weight: 700;
  line-height: 1.45;
  margin-block: 1.1em .6em;
  text-shadow: none;
}

#chat .mes_text h1 {
  font-size: 1.5em;
}

#chat .mes_text h2 {
  font-size: 1.3em;
}

#chat .mes_text h3 {
  font-size: 1.15em;
}

#chat .mes_text strong {
  color: var(--theme-text-primary);
  font-weight: 700;
}

#chat .mes_text em, #chat .mes_text i:not([class*="fa-"]):not([class*="icon"]) {
  color: var(--theme-leaf);
}

#chat .mes_text q {
  color: var(--theme-text-primary);
  background-color: var(--theme-quote);
  border-radius: .4em;
  padding: .12em .25em;
  box-decoration-break: clone;
}

#chat .mes_text blockquote {
  color: var(--theme-text-primary);
  background-color: var(--theme-quote);
  border-color: var(--theme-border);
  opacity: var(--theme-opacity-full);
  filter: var(--theme-effect-none);
  text-shadow: var(--theme-effect-none);
  box-shadow: var(--theme-effect-none);
  border-inline-start: 3px solid var(--theme-gold);
  border-radius: 2px 16px 16px 2px;
  margin: .85em 0;
  padding: .65em 1em;
}

#chat .mes_text :is(ul,ol) {
  padding-inline-start: 1.65em;
  margin-block: .7em 1em;
}

#chat .mes_text li {
  padding-inline-start: .2em;
  margin-block: .35em;
}

#chat .mes_text li::marker {
  color: var(--theme-leaf);
  font-weight: 700;
}

#chat .mes_text a {
  color: var(--theme-focus-ring);
  text-decoration-color: var(--theme-gold);
  text-underline-offset: .2em;
}

#chat .mes_text a:focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: 2px;
}

#chat .mes_text hr {
  border: 0;
  border-top: 1px solid var(--theme-border);
  margin-block: 1.4em;
  opacity: 1;
}

#chat .mes_text table {
  color: var(--theme-text-primary);
  background-color: var(--theme-surface-muted);
  border-color: var(--theme-border);
  opacity: var(--theme-opacity-full);
  filter: var(--theme-effect-none);
  text-shadow: var(--theme-effect-none);
  box-shadow: var(--theme-effect-none);
  display: block;
  max-inline-size: 100%;
  overflow-x: auto;
  border-collapse: collapse;
}

#chat .mes_text :is(th,td) {
  border: 1px solid var(--theme-border);
  padding: .45em .7em;
}

#chat .mes_text th {
  background-color: var(--theme-quote);
  color: var(--theme-text-primary);
  font-weight: 700;
}

#chat .mes_text :is(img,video,iframe) {
  max-inline-size: 100%;
  border-radius: 10px;
}

#chat .mes_text :is(details,summary) {
  color: var(--theme-text-primary);
}

#chat .mes_text summary {
  background-color: var(--theme-surface-muted);
  border-radius: 10px;
  padding: .35em .6em;
}


/* src/windows/topbar.css */
#top-bar, body.no-blur #top-bar {
  color: var(--theme-text-primary) !important;
  background-color: var(--theme-surface-muted) !important;
  border-color: var(--theme-border) !important;
  opacity: var(--theme-opacity-full) !important;
  filter: var(--theme-effect-none) !important;
  text-shadow: var(--theme-effect-none) !important;
  box-shadow: var(--theme-raised) !important;
  background-image: var(--theme-enamel) !important;
  border: 3px solid var(--theme-surface) !important;
  border-radius: 0 0 22px 22px !important;
  height: var(--topBarBlockSize) !important;
  backdrop-filter: none !important;
}

#top-settings-holder > .drawer > .drawer-toggle {
  padding: .18em 0;
}

#top-settings-holder .drawer-toggle .drawer-icon {
  color: var(--theme-text-secondary) !important;
